function makeCounter() {
  let count = 0;                 // biến "riêng tư" của closure
  return function () {
    count++;
    return count;
  };
}

const a = makeCounter();
console.log(a(), a(), a());      // 1 2 3

const b = makeCounter();         // bộ đếm khác, độc lập
console.log(b());                // 1

// Hàm bậc cao: nhận hàm làm đối số
function repeat(n, action) {
  for (let i = 0; i < n; i++) action(i);
}
repeat(3, (i) => console.log("lần", i));

